PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT NOT NULL UNIQUE, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'USER', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS auth_tokens (token_hash TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS categories (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE, icon TEXT NOT NULL DEFAULT 'grid');
CREATE TABLE IF NOT EXISTS skill_groups (id INTEGER PRIMARY KEY AUTOINCREMENT, category_id INTEGER NOT NULL REFERENCES categories(id), name TEXT NOT NULL, description TEXT, UNIQUE (category_id, name));
CREATE TABLE IF NOT EXISTS skills (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, normalized_name TEXT NOT NULL, description TEXT, group_id INTEGER NOT NULL REFERENCES skill_groups(id), creator_id INTEGER REFERENCES users(id) ON DELETE SET NULL, source_type TEXT NOT NULL, status TEXT NOT NULL, difficulty INTEGER NOT NULL DEFAULT 2, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_skill_name ON skills(normalized_name);
CREATE TABLE IF NOT EXISTS skill_aliases (id INTEGER PRIMARY KEY AUTOINCREMENT, skill_id INTEGER NOT NULL REFERENCES skills(id) ON DELETE CASCADE, alias TEXT NOT NULL, normalized_alias TEXT NOT NULL, UNIQUE (skill_id, normalized_alias));
CREATE TABLE IF NOT EXISTS skill_reviews (skill_id INTEGER PRIMARY KEY REFERENCES skills(id) ON DELETE CASCADE, reason TEXT NOT NULL, reviewed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS user_skills (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, skill_id INTEGER NOT NULL REFERENCES skills(id) ON DELETE CASCADE, level INTEGER NOT NULL DEFAULT 1, status TEXT NOT NULL DEFAULT 'WANT_TO_LEARN', note TEXT, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (user_id, skill_id));
CREATE TABLE IF NOT EXISTS trees (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL, description TEXT, visibility TEXT NOT NULL DEFAULT 'PRIVATE', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS tree_nodes (id INTEGER PRIMARY KEY AUTOINCREMENT, tree_id INTEGER NOT NULL REFERENCES trees(id) ON DELETE CASCADE, skill_id INTEGER NOT NULL REFERENCES skills(id), x REAL NOT NULL, y REAL NOT NULL, custom_label TEXT, UNIQUE (tree_id, skill_id));
CREATE TABLE IF NOT EXISTS tree_edges (id INTEGER PRIMARY KEY AUTOINCREMENT, tree_id INTEGER NOT NULL REFERENCES trees(id) ON DELETE CASCADE, source_node_id INTEGER NOT NULL REFERENCES tree_nodes(id) ON DELETE CASCADE, target_node_id INTEGER NOT NULL REFERENCES tree_nodes(id) ON DELETE CASCADE, UNIQUE (tree_id, source_node_id, target_node_id));
